import{CONFIG}from"../config.js";const COLORS={kinetic:"#dbeeff",toxic:"#82ff9e",frost:"#79e8ff",volt:"#bd8cff",ember:"#ff9a62"};export class Effects{constructor(runtime,rng){this.runtime=runtime;this.rng=rng}spark(x,y,element="kinetic",count=10){const c=COLORS[element]||element||"#fff";for(let i=0;i<count&&this.runtime.effects.length<CONFIG.renderer.maxParticles;i++){const a=this.rng()*Math.PI*2,s=45+this.rng()*180;this.runtime.effects.push({type:"particle",x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,g:85,life:.28+this.rng()*.45,size:1.5+this.rng()*4.5,color:c})}}ring(x,y,color="#72e7ff"){this.runtime.effects.push({type:"ring",x,y,r:8,life:.48,color})}text(x,y,text,color="#fff"){this.runtime.texts.push({x,y,text,color,life:.75})}update(dt){for(const p of[...this.runtime.effects]){p.life-=dt;if(p.type==="particle"){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.g*dt;p.size*=.984}if(p.type==="ring")p.r+=dt*240;if(p.life<=0)this.runtime.effects.splice(this.runtime.effects.indexOf(p),1)}for(const t of[...this.runtime.texts]){t.life-=dt;t.y-=23*dt;if(t.life<=0)this.runtime.texts.splice(this.runtime.texts.indexOf(t),1)}}}
